BEGIN;
CREATE SCHEMA erp_inventory_private;
REVOKE ALL ON SCHEMA erp_inventory_private FROM PUBLIC,anon,authenticated,service_role;
CREATE TABLE public.erp_inventory_catalogs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),cafe_id uuid NOT NULL REFERENCES public.cafes(id),kind text NOT NULL CHECK(kind IN('category','brand','unit_template','group')),name text NOT NULL CHECK(length(btrim(name)) BETWEEN 1 AND 150),active boolean NOT NULL DEFAULT true,payload jsonb NOT NULL DEFAULT '{}',revision integer NOT NULL DEFAULT 1,UNIQUE(cafe_id,id),UNIQUE(cafe_id,kind,name),parent_id uuid,FOREIGN KEY(cafe_id,parent_id) REFERENCES public.erp_inventory_catalogs(cafe_id,id));
CREATE TABLE public.erp_inventory_items(cafe_id uuid NOT NULL,item_id uuid NOT NULL,kind text NOT NULL DEFAULT 'product' CHECK(kind IN('product','service','work')),status text NOT NULL DEFAULT 'active' CHECK(status IN('active','inactive','stopped')),category_id uuid,brand_id uuid,unit_template_id uuid,group_id uuid,payload jsonb NOT NULL DEFAULT '{}',revision integer NOT NULL DEFAULT 1,PRIMARY KEY(cafe_id,item_id),FOREIGN KEY(cafe_id,item_id) REFERENCES public.bf_items(cafe_id,id),FOREIGN KEY(cafe_id,category_id) REFERENCES public.erp_inventory_catalogs(cafe_id,id),FOREIGN KEY(cafe_id,brand_id) REFERENCES public.erp_inventory_catalogs(cafe_id,id),FOREIGN KEY(cafe_id,unit_template_id) REFERENCES public.erp_inventory_catalogs(cafe_id,id),FOREIGN KEY(cafe_id,group_id) REFERENCES public.erp_inventory_catalogs(cafe_id,id));
ALTER TABLE public.bf_warehouses ADD COLUMN is_default boolean NOT NULL DEFAULT false;
ALTER TABLE public.bf_warehouses ADD COLUMN inventory_payload jsonb NOT NULL DEFAULT '{}';
ALTER TABLE public.bf_warehouses ADD COLUMN inventory_revision integer NOT NULL DEFAULT 1;
-- Preserve the active warehouse previously selected by existing finance consumers
UPDATE public.bf_warehouses w SET is_default=true FROM (SELECT DISTINCT ON(cafe_id) cafe_id,id FROM public.bf_warehouses WHERE active ORDER BY cafe_id,name,id) chosen WHERE chosen.id=w.id;
CREATE UNIQUE INDEX bf_warehouse_default ON public.bf_warehouses(cafe_id) WHERE is_default;
CREATE TABLE public.erp_inventory_employee_warehouses(cafe_id uuid NOT NULL,employee_id uuid NOT NULL,warehouse_id uuid NOT NULL,PRIMARY KEY(cafe_id,employee_id),FOREIGN KEY(cafe_id,employee_id) REFERENCES public.erp_hr_employees(cafe_id,id),FOREIGN KEY(cafe_id,warehouse_id) REFERENCES public.bf_warehouses(cafe_id,id));
CREATE TABLE public.erp_inventory_settings(cafe_id uuid PRIMARY KEY REFERENCES public.cafes(id),payload jsonb NOT NULL DEFAULT '{}',revision integer NOT NULL DEFAULT 1);
CREATE TABLE public.erp_inventory_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),cafe_id uuid NOT NULL REFERENCES public.cafes(id),number bigint GENERATED ALWAYS AS IDENTITY,code text NOT NULL,kind text NOT NULL CHECK(kind IN('receipt','issue','transfer','stocktake','request')),status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','pending','counted','posted','cancelled','reversed')),warehouse_id uuid NOT NULL,to_warehouse_id uuid,party_id uuid,effective_on date NOT NULL DEFAULT current_date,source_mode text NOT NULL DEFAULT 'standalone' CHECK(source_mode IN('standalone','financial')),finance_document_id uuid,reversal_document_id uuid,request_document_id uuid,payload jsonb NOT NULL DEFAULT '{}',revision integer NOT NULL DEFAULT 1,created_by uuid NOT NULL REFERENCES auth.users(id),created_at timestamptz NOT NULL DEFAULT now(),posted_at timestamptz,UNIQUE(cafe_id,id),UNIQUE(cafe_id,kind,code),UNIQUE(cafe_id,finance_document_id),FOREIGN KEY(cafe_id,warehouse_id) REFERENCES public.bf_warehouses(cafe_id,id),FOREIGN KEY(cafe_id,to_warehouse_id) REFERENCES public.bf_warehouses(cafe_id,id),FOREIGN KEY(cafe_id,party_id) REFERENCES public.bf_parties(cafe_id,id),FOREIGN KEY(cafe_id,finance_document_id) REFERENCES public.bf_documents(cafe_id,id),FOREIGN KEY(cafe_id,reversal_document_id) REFERENCES public.bf_documents(cafe_id,id),FOREIGN KEY(cafe_id,request_document_id) REFERENCES public.erp_inventory_documents(cafe_id,id));
CREATE INDEX erp_inventory_document_list ON public.erp_inventory_documents(cafe_id,kind,effective_on DESC);
CREATE UNIQUE INDEX erp_inventory_fulfilled_request ON public.erp_inventory_documents(cafe_id,request_document_id) WHERE request_document_id IS NOT NULL AND status<>'cancelled';
CREATE TABLE public.erp_inventory_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),cafe_id uuid NOT NULL,document_id uuid NOT NULL,item_id uuid NOT NULL,quantity numeric(16,3) NOT NULL CHECK(quantity>=0 AND quantity<=1000000 AND quantity<>'NaN'),factor numeric(16,6) NOT NULL DEFAULT 1 CHECK(factor>0 AND factor<=1000000 AND factor<>'NaN'),unit_name text NOT NULL DEFAULT '',unit_cost numeric(18,6) NOT NULL DEFAULT 0 CHECK(unit_cost>=0 AND unit_cost<=1000000000 AND unit_cost<>'NaN'),expected_quantity numeric(16,3),counted_quantity numeric(16,3),payload jsonb NOT NULL DEFAULT '{}',position integer NOT NULL,UNIQUE(cafe_id,document_id,item_id),FOREIGN KEY(cafe_id,document_id) REFERENCES public.erp_inventory_documents(cafe_id,id) ON DELETE CASCADE,FOREIGN KEY(cafe_id,item_id) REFERENCES public.bf_items(cafe_id,id),CHECK(counted_quantity IS NULL OR counted_quantity BETWEEN 0 AND 1000000 AND counted_quantity<>'NaN'));
CREATE TABLE public.erp_inventory_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),cafe_id uuid NOT NULL REFERENCES public.cafes(id),record_id uuid NOT NULL,action text NOT NULL,detail jsonb NOT NULL DEFAULT '{}',actor uuid NOT NULL REFERENCES auth.users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX erp_inventory_events_record ON public.erp_inventory_events(cafe_id,record_id,created_at DESC);
CREATE TRIGGER erp_inventory_events_immutable BEFORE UPDATE OR DELETE ON public.erp_inventory_events FOR EACH ROW EXECUTE FUNCTION brand_finance_private.immutable();
CREATE TABLE erp_inventory_private.requests(cafe_id uuid NOT NULL REFERENCES public.cafes(id),request_id uuid NOT NULL,actor uuid NOT NULL REFERENCES auth.users(id),payload jsonb NOT NULL,result jsonb NOT NULL,PRIMARY KEY(cafe_id,request_id));
CREATE TABLE erp_inventory_private.movement_order(sequence bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,movement_id uuid NOT NULL UNIQUE REFERENCES public.bf_movements(id),cafe_id uuid NOT NULL,item_id uuid NOT NULL,warehouse_id uuid NOT NULL);
CREATE INDEX erp_inventory_movement_version ON erp_inventory_private.movement_order(cafe_id,item_id,warehouse_id,sequence);
CREATE FUNCTION erp_inventory_private.record_movement_order() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$BEGIN INSERT INTO erp_inventory_private.movement_order(movement_id,cafe_id,item_id,warehouse_id) VALUES(NEW.id,NEW.cafe_id,NEW.item_id,NEW.warehouse_id);RETURN NEW;END $$;
CREATE TRIGGER erp_inventory_movement_order AFTER INSERT ON public.bf_movements FOR EACH ROW EXECUTE FUNCTION erp_inventory_private.record_movement_order();
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['catalogs','items','employee_warehouses','settings','documents','lines','events'] LOOP EXECUTE format('ALTER TABLE public.erp_inventory_%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON public.erp_inventory_%I FROM PUBLIC,anon,authenticated,service_role',t);END LOOP;END $$;
REVOKE ALL ON ALL TABLES IN SCHEMA erp_inventory_private FROM PUBLIC,anon,authenticated,service_role;
DO $$ DECLARE domains text[];BEGIN SELECT array_agg(domain ORDER BY position) INTO domains FROM(SELECT domain,min(position) position FROM unnest(erp_access_private.domains()||ARRAY['inventory']) WITH ORDINALITY t(domain,position) GROUP BY domain) x;EXECUTE format('CREATE OR REPLACE FUNCTION erp_access_private.domains() RETURNS text[] LANGUAGE sql IMMUTABLE SET search_path='''' AS $f$SELECT %L::text[]$f$',domains);UPDATE public.erp_roles SET permissions=jsonb_build_object('inventory',jsonb_build_object('read',false,'create',false,'update',false,'delete',false,'approve',false,'settings',false,'files',false))||permissions;END $$;
CREATE FUNCTION erp_inventory_private.authorize(p_cafe uuid,p_action text DEFAULT 'read') RETURNS text LANGUAGE plpgsql SET search_path='' AS $$DECLARE r text;BEGIN r:=brand_finance_private.role_for(p_cafe);IF r NOT IN('owner','manager','warehouse','accountant','auditor') OR p_action<>'read' AND r NOT IN('owner','manager','warehouse') THEN RAISE EXCEPTION 'لا تملك صلاحية المخزون' USING ERRCODE='42501';END IF;PERFORM erp_access_private.assert_allowed(p_cafe,'inventory',p_action);RETURN r;END $$;
CREATE FUNCTION erp_inventory_private.warehouse_allowed(p_cafe uuid,p_warehouse uuid,p_action text DEFAULT 'read') RETURNS boolean LANGUAGE plpgsql STABLE SET search_path='' AS $$DECLARE r text;rule jsonb;mode text;BEGIN
 r:=brand_finance_private.role_for(p_cafe);IF r IN('owner','manager') THEN RETURN EXISTS(SELECT 1 FROM public.bf_warehouses WHERE cafe_id=p_cafe AND id=p_warehouse);END IF;
 SELECT inventory_payload->'permissions'->p_action INTO rule FROM public.bf_warehouses WHERE cafe_id=p_cafe AND id=p_warehouse;IF NOT FOUND THEN RETURN false;END IF;mode:=coalesce(rule->>'mode','all');
 RETURN CASE mode WHEN 'all' THEN true WHEN 'employees' THEN EXISTS(SELECT 1 FROM public.erp_hr_employees e WHERE e.cafe_id=p_cafe AND e.user_id=auth.uid() AND e.active AND rule->'ids' ? e.id::text) WHEN 'roles' THEN rule->'ids' ? r WHEN 'branches' THEN EXISTS(SELECT 1 FROM public.erp_hr_employees e WHERE e.cafe_id=p_cafe AND e.user_id=auth.uid() AND e.active AND rule->'ids' ? e.branch_id::text) ELSE false END;
END $$;
CREATE FUNCTION erp_inventory_private.default_warehouse(p_cafe uuid,p_user uuid DEFAULT auth.uid()) RETURNS uuid LANGUAGE sql STABLE SET search_path='' AS $$SELECT w.id FROM public.bf_warehouses w WHERE w.cafe_id=p_cafe AND w.active AND erp_inventory_private.warehouse_allowed(p_cafe,w.id,'read') ORDER BY EXISTS(SELECT 1 FROM public.erp_inventory_employee_warehouses d JOIN public.erp_hr_employees e ON e.cafe_id=d.cafe_id AND e.id=d.employee_id WHERE d.cafe_id=p_cafe AND d.warehouse_id=w.id AND e.user_id=p_user AND e.active) DESC,w.is_default DESC,w.name,w.id LIMIT 1$$;
CREATE OR REPLACE FUNCTION brand_finance_private.inventory_warehouse_guard() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(NEW.cafe_id::text,60412));IF NOT EXISTS(SELECT 1 FROM public.bf_warehouses WHERE cafe_id=NEW.cafe_id AND is_default) THEN NEW.is_default:=true;END IF;IF NEW.is_default AND NOT NEW.active THEN RAISE EXCEPTION 'يجب أن يكون المستودع الرئيسي نشطًا';END IF;RETURN NEW;END $$;
-- Preserve the public function OID and every existing wrapper, then apply deterministic defaults
DO $$ DECLARE definition text;BEGIN SELECT pg_get_functiondef('public.brand_finance_snapshot(uuid)'::regprocedure) INTO definition;EXECUTE replace(definition,'public.brand_finance_snapshot(','erp_inventory_private.snapshot_before_inventory(');END $$;
CREATE OR REPLACE FUNCTION public.brand_finance_snapshot(p_cafe_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE result jsonb;preferred uuid;BEGIN result:=erp_inventory_private.snapshot_before_inventory(p_cafe_id);preferred:=erp_inventory_private.default_warehouse(p_cafe_id);RETURN result||jsonb_build_object('defaultWarehouseId',preferred,'warehouses',coalesce((SELECT jsonb_agg(to_jsonb(w)-'cafe_id' ORDER BY w.id=preferred DESC,w.is_default DESC,w.name,w.id) FROM public.bf_warehouses w WHERE w.cafe_id=p_cafe_id AND erp_inventory_private.warehouse_allowed(p_cafe_id,w.id,'read')),'[]'::jsonb));END $$;
CREATE FUNCTION erp_inventory_private.assert_catalog(p_cafe uuid,p_id uuid,p_kind text) RETURNS void LANGUAGE plpgsql SET search_path='' AS $$BEGIN IF p_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.erp_inventory_catalogs WHERE cafe_id=p_cafe AND id=p_id AND kind=p_kind AND active) THEN RAISE EXCEPTION 'اختيار التصنيف أو القالب غير متاح';END IF;END $$;
CREATE FUNCTION erp_inventory_private.assert_open(p_cafe uuid,p_date date) RETURNS void LANGUAGE plpgsql SET search_path='' AS $$BEGIN IF p_date IS NULL OR p_date>current_date OR EXISTS(SELECT 1 FROM public.bf_settings WHERE cafe_id=p_cafe AND closed_through>=p_date) THEN RAISE EXCEPTION 'تاريخ العملية مستقبل أو ضمن فترة مقفلة';END IF;END $$;
CREATE FUNCTION erp_inventory_private.ean13(p_code text) RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$DECLARE total integer:=0;BEGIN IF p_code!~'^[0-9]{12}$' THEN RAISE EXCEPTION 'EAN 13 يحتاج ١٢ رقمًا قبل خانة التحقق';END IF;FOR n IN 1..12 LOOP total:=total+substring(p_code,n,1)::integer*CASE WHEN n%2=0 THEN 3 ELSE 1 END;END LOOP;RETURN p_code||((10-total%10)%10)::text;END $$;
CREATE FUNCTION erp_inventory_private.unit_factor(p_cafe uuid,p_item uuid,p_unit text) RETURNS numeric LANGUAGE plpgsql STABLE SET search_path='' AS $$DECLARE base text;template uuid;factor numeric;BEGIN SELECT i.unit,m.unit_template_id INTO base,template FROM public.bf_items i LEFT JOIN public.erp_inventory_items m ON m.cafe_id=i.cafe_id AND m.item_id=i.id WHERE i.cafe_id=p_cafe AND i.id=p_item AND i.active;IF NOT FOUND THEN RAISE EXCEPTION 'الصنف غير متاح';END IF;IF template IS NULL THEN IF p_unit=base OR nullif(p_unit,'') IS NULL THEN RETURN 1;END IF;ELSE SELECT (u->>'factor')::numeric INTO factor FROM public.erp_inventory_catalogs c,jsonb_array_elements(c.payload->'units') u WHERE c.cafe_id=p_cafe AND c.id=template AND u->>'name'=p_unit;IF FOUND THEN RETURN factor;END IF;END IF;RAISE EXCEPTION 'الوحدة غير متاحة للصنف';END $$;
-- Keep old inventory APIs under the same restrictive custom-role policy
DO $$ DECLARE definition text;BEGIN SELECT pg_get_functiondef('public.brand_finance_execute(uuid,text,jsonb,uuid)'::regprocedure) INTO definition;EXECUTE replace(definition,'public.brand_finance_execute(','erp_inventory_private.execute_before_inventory(');END $$;
CREATE OR REPLACE FUNCTION public.brand_finance_execute(p_cafe_id uuid,p_operation text,p_payload jsonb,p_request_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$BEGIN IF p_operation IN('item','warehouse','stock_adjust','stock_transfer') THEN PERFORM erp_access_private.assert_allowed(p_cafe_id,'inventory',CASE WHEN p_operation IN('stock_adjust','stock_transfer') THEN 'approve' WHEN nullif(p_payload->>'id','') IS NULL THEN 'create' ELSE 'update' END);END IF;RETURN erp_inventory_private.execute_before_inventory(p_cafe_id,p_operation,p_payload,p_request_id);END $$;
DO $$ DECLARE definition text;BEGIN SELECT pg_get_functiondef('brand_finance_private.stock_move(uuid,uuid,uuid,uuid,numeric,numeric)'::regprocedure) INTO definition;EXECUTE replace(definition,'brand_finance_private.stock_move(','erp_inventory_private.stock_move_before_inventory(');END $$;
CREATE OR REPLACE FUNCTION brand_finance_private.stock_move(p_cafe uuid,p_doc uuid,p_item uuid,p_warehouse uuid,p_quantity numeric,p_cost numeric) RETURNS numeric LANGUAGE plpgsql SET search_path='' AS $$DECLARE policy jsonb;BEGIN
 IF auth.uid() IS NOT NULL AND NOT erp_inventory_private.warehouse_allowed(p_cafe,p_warehouse,'write') THEN RAISE EXCEPTION 'لا تملك تنفيذ حركة في هذا المستودع' USING ERRCODE='42501';END IF;
 IF EXISTS(SELECT 1 FROM public.erp_inventory_items WHERE cafe_id=p_cafe AND item_id=p_item AND (kind<>'product' OR status<>'active')) THEN RAISE EXCEPTION 'الصنف موقوف أو غير مخزني';END IF;
 SELECT payload INTO policy FROM public.erp_inventory_settings WHERE cafe_id=p_cafe;IF policy->>'allowNegative'='false' AND p_quantity<0 AND coalesce((SELECT quantity FROM public.bf_stock WHERE cafe_id=p_cafe AND item_id=p_item AND warehouse_id=p_warehouse),0)+p_quantity<0 THEN RAISE EXCEPTION 'إعدادات المخزون تمنع الكمية السالبة';END IF;
 RETURN erp_inventory_private.stock_move_before_inventory(p_cafe,p_doc,p_item,p_warehouse,p_quantity,p_cost);
END $$;
CREATE FUNCTION erp_inventory_private.register_purchase_pending(p_cafe uuid,p_invoice uuid) RETURNS uuid LANGUAGE plpgsql SET search_path='' AS $$DECLARE d public.bf_documents%ROWTYPE;saved uuid;BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,60412));SELECT id INTO saved FROM public.erp_inventory_documents WHERE cafe_id=p_cafe AND source_mode='financial' AND payload->>'sourceInvoiceId'=p_invoice::text;IF FOUND THEN RETURN saved;END IF;
 SELECT * INTO d FROM public.bf_documents WHERE cafe_id=p_cafe AND id=p_invoice AND kind='purchase';IF d.id IS NULL OR d.warehouse_id IS NULL THEN RAISE EXCEPTION 'فاتورة الشراء غير متاحة';END IF;
 IF EXISTS(SELECT 1 FROM public.bf_movements WHERE cafe_id=p_cafe AND document_id=p_invoice) THEN RETURN erp_inventory_private.acknowledge_finance(p_cafe,p_invoice);END IF;
 INSERT INTO public.erp_inventory_documents(cafe_id,code,kind,status,warehouse_id,party_id,effective_on,source_mode,payload,created_by) VALUES(p_cafe,'FIN-'||d.number,'receipt','pending',d.warehouse_id,d.party_id,(d.created_at AT TIME ZONE 'Asia/Riyadh')::date,'financial',jsonb_build_object('sourceInvoiceId',d.id,'note',d.note),d.created_by) RETURNING id INTO saved;
 INSERT INTO public.erp_inventory_lines(cafe_id,document_id,item_id,quantity,unit_cost,position) SELECT p_cafe,saved,item_id,sum(quantity),sum(net)/sum(quantity),row_number() OVER(ORDER BY item_id) FROM public.bf_document_lines WHERE cafe_id=p_cafe AND document_id=d.id AND item_id IS NOT NULL GROUP BY item_id;RETURN saved;
END $$;
CREATE FUNCTION erp_inventory_private.save_lines(p_cafe uuid,p_id uuid,p_lines jsonb) RETURNS void LANGUAGE plpgsql SET search_path='' AS $$DECLARE d public.erp_inventory_documents%ROWTYPE;l jsonb;i public.bf_items%ROWTYPE;meta public.erp_inventory_items%ROWTYPE;q numeric;f numeric;expected numeric;position integer:=0;BEGIN
 SELECT * INTO STRICT d FROM public.erp_inventory_documents WHERE cafe_id=p_cafe AND id=p_id;
 IF jsonb_typeof(p_lines) IS DISTINCT FROM 'array' OR jsonb_array_length(p_lines)>500 THEN RAISE EXCEPTION 'البنود غير صالحة أو تجاوزت ٥٠٠ بند';END IF;
 DELETE FROM public.erp_inventory_lines WHERE cafe_id=p_cafe AND document_id=p_id;
 FOR l IN SELECT value FROM jsonb_array_elements(p_lines) LOOP
 SELECT * INTO i FROM public.bf_items WHERE cafe_id=p_cafe AND id=(l->>'itemId')::uuid AND active;IF NOT FOUND THEN RAISE EXCEPTION 'اختر صنفًا نشطًا من العلامة';END IF;
 SELECT * INTO meta FROM public.erp_inventory_items WHERE cafe_id=p_cafe AND item_id=i.id;IF meta.kind IN('service','work') OR meta.status IN('stopped','inactive') THEN RAISE EXCEPTION 'هذا البند لا يقبل حركة مخزنية';END IF;
 f:=coalesce((l->>'factor')::numeric,1);q:=coalesce((l->>'quantity')::numeric,0);IF f IS DISTINCT FROM erp_inventory_private.unit_factor(p_cafe,i.id,coalesce(nullif(l->>'unitName',''),i.unit)) THEN RAISE EXCEPTION 'معامل الوحدة غير مسجل للصنف';END IF;
 IF round(q*f,3)<>q*f OR q*f>1000000 THEN RAISE EXCEPTION 'الكمية المحولة تتجاوز الدقة أو الحد المسموح';END IF;
 IF nullif(l->>'countedQuantity','') IS NOT NULL AND ((l->>'countedQuantity')::numeric<>round((l->>'countedQuantity')::numeric,3) OR (l->>'countedQuantity')::numeric*f<>round((l->>'countedQuantity')::numeric*f,3) OR (l->>'countedQuantity')::numeric*f>1000000) THEN RAISE EXCEPTION 'دقة العدد الفعلي أو الكمية المحولة غير صالحة';END IF;
 SELECT coalesce(sum(quantity),0) INTO expected FROM public.bf_stock WHERE cafe_id=p_cafe AND item_id=i.id AND warehouse_id=d.warehouse_id;
 INSERT INTO public.erp_inventory_lines(cafe_id,document_id,item_id,quantity,factor,unit_name,unit_cost,expected_quantity,counted_quantity,payload,position) VALUES(p_cafe,p_id,i.id,q,f,coalesce(l->>'unitName',i.unit),coalesce((l->>'unitCost')::numeric,0),coalesce((l->>'expectedQuantity')::numeric,expected),nullif(l->>'countedQuantity','')::numeric,coalesce(l->'payload','{}'),position);
 position:=position+1;END LOOP;
END $$;
-- A finance purchase has already moved stock; acknowledgement must never post it again
CREATE FUNCTION erp_inventory_private.acknowledge_finance(p_cafe uuid,p_document uuid) RETURNS uuid LANGUAGE plpgsql SET search_path='' AS $$DECLARE d public.bf_documents%ROWTYPE;saved uuid;receipt boolean;BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,60412));SELECT id INTO saved FROM public.erp_inventory_documents WHERE cafe_id=p_cafe AND finance_document_id=p_document;IF FOUND THEN RETURN saved;END IF;
 SELECT * INTO d FROM public.bf_documents WHERE cafe_id=p_cafe AND id=p_document;IF d.id IS NULL OR d.warehouse_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.bf_movements WHERE cafe_id=p_cafe AND document_id=d.id) THEN RAISE EXCEPTION 'المستند لا يحتوي حركة مخزنية مرحلة';END IF;
 receipt:=NOT EXISTS(SELECT 1 FROM public.bf_movements WHERE cafe_id=p_cafe AND document_id=d.id AND quantity<0);
 SELECT id INTO saved FROM public.erp_inventory_documents WHERE cafe_id=p_cafe AND status='pending' AND source_mode='financial' AND payload->>'sourceInvoiceId'=coalesce(d.reference_id,d.id)::text FOR UPDATE;
 IF FOUND THEN UPDATE public.erp_inventory_documents SET status='posted',finance_document_id=d.id,posted_at=now(),revision=revision+1 WHERE cafe_id=p_cafe AND id=saved;
 ELSE INSERT INTO public.erp_inventory_documents(cafe_id,code,kind,status,warehouse_id,party_id,effective_on,source_mode,finance_document_id,payload,created_by,posted_at) VALUES(p_cafe,'FIN-'||d.number,CASE WHEN receipt THEN 'receipt' ELSE 'issue' END,'posted',d.warehouse_id,d.party_id,(d.created_at AT TIME ZONE 'Asia/Riyadh')::date,'financial',d.id,jsonb_build_object('note',d.note,'financialKind',d.kind,'sourceInvoiceId',CASE WHEN d.kind='purchase' THEN d.id ELSE d.reference_id END),d.created_by,d.created_at) RETURNING id INTO saved;END IF;
 DELETE FROM public.erp_inventory_lines WHERE cafe_id=p_cafe AND document_id=saved;
 INSERT INTO public.erp_inventory_lines(cafe_id,document_id,item_id,quantity,unit_cost,position) SELECT p_cafe,saved,m.item_id,abs(sum(m.quantity)),sum(abs(m.quantity)*m.unit_cost)/abs(sum(m.quantity)),row_number() OVER(ORDER BY m.item_id) FROM public.bf_movements m WHERE m.cafe_id=p_cafe AND m.document_id=d.id AND m.warehouse_id=d.warehouse_id GROUP BY m.item_id HAVING sum(m.quantity)<>0;
 INSERT INTO public.erp_inventory_events(cafe_id,record_id,action,detail,actor) VALUES(p_cafe,saved,'financial_acknowledgement',jsonb_build_object('financeDocumentId',d.id),coalesce(auth.uid(),d.created_by));RETURN saved;
END $$;
CREATE FUNCTION erp_inventory_private.post(p_cafe uuid,p_id uuid) RETURNS uuid LANGUAGE plpgsql SET search_path='' AS $$DECLARE d public.erp_inventory_documents%ROWTYPE;l public.erp_inventory_lines%ROWTYPE;fid uuid:=gen_random_uuid();actual numeric;delta numeric;cost numeric;offset_account uuid;BEGIN
 SELECT * INTO STRICT d FROM public.erp_inventory_documents WHERE cafe_id=p_cafe AND id=p_id FOR UPDATE;
 IF d.status='posted' THEN RETURN d.finance_document_id;END IF;
 IF d.source_mode<>'standalone' OR d.kind='request' OR d.status NOT IN('draft','pending','counted') OR d.kind='stocktake' AND d.status<>'counted' THEN RAISE EXCEPTION 'حالة المستند لا تسمح بالترحيل';END IF;
 PERFORM erp_inventory_private.assert_open(p_cafe,d.effective_on);PERFORM erp_inventory_private.assert_open(p_cafe,current_date);
 IF NOT EXISTS(SELECT 1 FROM public.bf_warehouses WHERE cafe_id=p_cafe AND id=d.warehouse_id AND active) OR NOT erp_inventory_private.warehouse_allowed(p_cafe,d.warehouse_id,'write') THEN RAISE EXCEPTION 'المستودع غير متاح';END IF;
 IF d.kind='transfer' AND (d.to_warehouse_id IS NULL OR d.to_warehouse_id=d.warehouse_id OR NOT EXISTS(SELECT 1 FROM public.bf_warehouses WHERE cafe_id=p_cafe AND id=d.to_warehouse_id AND active) OR NOT erp_inventory_private.warehouse_allowed(p_cafe,d.to_warehouse_id,'write')) THEN RAISE EXCEPTION 'اختر مستودع وجهة مختلفًا ومتاحًا';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.erp_inventory_lines WHERE cafe_id=p_cafe AND document_id=p_id) THEN RAISE EXCEPTION 'أضف بندًا واحدًا على الأقل';END IF;
 offset_account:=coalesce(nullif(d.payload->>'accountId','')::uuid,brand_finance_private.account(p_cafe,'5200'));IF NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=p_cafe AND id=offset_account AND active AND kind IN('expense','equity')) THEN RAISE EXCEPTION 'اختر حساب تسوية مصروف أو حقوق ملكية';END IF;
 INSERT INTO public.bf_documents(id,cafe_id,kind,warehouse_id,note,created_by,created_at) VALUES(fid,p_cafe,CASE WHEN d.kind='transfer' THEN 'stock_transfer' ELSE 'stock_adjust' END,d.warehouse_id,left(coalesce(d.payload->>'note','')||' / '||d.code,1000),auth.uid(),CASE WHEN d.effective_on=(now() AT TIME ZONE 'Asia/Riyadh')::date THEN now() ELSE d.effective_on::timestamp AT TIME ZONE 'Asia/Riyadh' END);
 FOR l IN SELECT * FROM public.erp_inventory_lines WHERE cafe_id=p_cafe AND document_id=p_id ORDER BY item_id LOOP
 SELECT coalesce(sum(quantity),0) INTO actual FROM public.bf_stock WHERE cafe_id=p_cafe AND warehouse_id=d.warehouse_id AND item_id=l.item_id;
 IF d.kind='stocktake' THEN IF l.counted_quantity IS NULL THEN RAISE EXCEPTION 'سجل العدد الفعلي لكل صنف';END IF;IF actual IS DISTINCT FROM l.expected_quantity THEN RAISE EXCEPTION 'تغير رصيد المخزون حدث العدد بالبرنامج قبل التسوية';END IF;delta:=round(l.counted_quantity*l.factor,3)-actual;
 ELSE IF l.quantity<=0 THEN RAISE EXCEPTION 'يجب أن تكون كمية كل بند موجبة';END IF;delta:=round(l.quantity*l.factor,3)*CASE WHEN d.kind IN('issue','transfer') THEN -1 ELSE 1 END;END IF;
 IF delta<>0 THEN cost:=brand_finance_private.stock_move(p_cafe,fid,l.item_id,d.warehouse_id,delta,l.unit_cost/l.factor);IF d.kind='transfer' THEN PERFORM brand_finance_private.stock_move(p_cafe,fid,l.item_id,d.to_warehouse_id,-delta,cost/abs(delta));ELSE PERFORM brand_finance_private.line(p_cafe,fid,brand_finance_private.account(p_cafe,'1200'),CASE WHEN delta>0 THEN cost ELSE 0 END,CASE WHEN delta<0 THEN cost ELSE 0 END);PERFORM brand_finance_private.line(p_cafe,fid,offset_account,CASE WHEN delta<0 THEN cost ELSE 0 END,CASE WHEN delta>0 THEN cost ELSE 0 END);END IF;END IF;
 END LOOP;
 UPDATE public.erp_inventory_documents SET status='posted',finance_document_id=fid,posted_at=now(),revision=revision+1 WHERE cafe_id=p_cafe AND id=p_id;
 RETURN fid;
END $$;
CREATE FUNCTION erp_inventory_private.reverse(p_cafe uuid,p_id uuid) RETURNS uuid LANGUAGE plpgsql SET search_path='' AS $$DECLARE d public.erp_inventory_documents%ROWTYPE;m public.bf_movements%ROWTYPE;j public.bf_journal%ROWTYPE;fid uuid:=gen_random_uuid();BEGIN
 SELECT * INTO STRICT d FROM public.erp_inventory_documents WHERE cafe_id=p_cafe AND id=p_id FOR UPDATE;IF d.status<>'posted' OR d.source_mode<>'standalone' THEN RAISE EXCEPTION 'اعكس المستند المالي الأصلي أو اختر إذنًا مرحلًا مستقلًا';END IF;PERFORM erp_inventory_private.assert_open(p_cafe,current_date);
 IF EXISTS(SELECT 1 FROM public.bf_movements original JOIN erp_inventory_private.movement_order origin_order ON origin_order.movement_id=original.id JOIN erp_inventory_private.movement_order later ON later.cafe_id=original.cafe_id AND later.item_id=original.item_id AND later.warehouse_id=original.warehouse_id AND later.sequence>origin_order.sequence WHERE original.cafe_id=p_cafe AND original.document_id=d.finance_document_id) THEN RAISE EXCEPTION 'توجد حركات لاحقة على البنود عالجها قبل التراجع';END IF;
 INSERT INTO public.bf_documents(id,cafe_id,kind,warehouse_id,reference_id,note,created_by) VALUES(fid,p_cafe,CASE WHEN d.kind='transfer' THEN 'stock_transfer' ELSE 'stock_adjust' END,d.warehouse_id,d.finance_document_id,'عكس إذن '||d.code,auth.uid());
 FOR m IN SELECT * FROM public.bf_movements WHERE cafe_id=p_cafe AND document_id=d.finance_document_id ORDER BY quantity DESC,item_id LOOP PERFORM brand_finance_private.stock_move(p_cafe,fid,m.item_id,m.warehouse_id,-m.quantity,m.unit_cost);END LOOP;
 FOR j IN SELECT * FROM public.bf_journal WHERE cafe_id=p_cafe AND document_id=d.finance_document_id LOOP PERFORM brand_finance_private.line(p_cafe,fid,j.account_id,j.credit,j.debit,j.party_id);END LOOP;
 UPDATE public.erp_inventory_documents SET status='reversed',reversal_document_id=fid,revision=revision+1 WHERE cafe_id=p_cafe AND id=p_id;RETURN fid;
END $$;
DO $$ DECLARE definition text;BEGIN
 SELECT pg_get_functiondef('erp_manufacturing_private.validate_custom_values(jsonb,jsonb,uuid,uuid,text,integer,boolean)'::regprocedure) INTO definition;
 definition:=replace(definition,'erp_manufacturing_private.validate_custom_values','erp_inventory_private.validate_custom_values');definition:=replace(definition,'''employees'' THEN ''bf_staff''','''employees'' THEN ''erp_hr_employees''');definition:=replace(definition,'CASE p_kind WHEN ''orders'' THEN ''manufacturing_order'' ELSE ''manufacturing_plan'' END','''inventory_item''');definition:=replace(definition,'p_kind IN(''orders'',''plans'')','p_kind=''item''');definition:=replace(definition,'CASE p_kind WHEN ''orders'' THEN ''erp_mfg_orders'' ELSE ''erp_mfg_plans'' END','''erp_inventory_items''');definition:=replace(definition,'AND id IS DISTINCT FROM $2 AND payload','AND item_id IS DISTINCT FROM $2 AND payload');EXECUTE definition;
END $$;
CREATE FUNCTION erp_inventory_private.save_item(p_cafe uuid,p jsonb) RETURNS uuid LANGUAGE plpgsql SET search_path='' AS $$<<save_item>> DECLARE saved uuid:=nullif(p->>'id','')::uuid;old public.erp_inventory_items%ROWTYPE;result jsonb;category uuid:=nullif(p->>'categoryId','')::uuid;brand uuid:=nullif(p->>'brandId','')::uuid;template uuid:=nullif(p->>'unitTemplateId','')::uuid;grp uuid:=nullif(p->>'groupId','')::uuid;cfg jsonb;n bigint;code text;key text;barcode text;f public.erp_files%ROWTYPE;BEGIN
 SELECT * INTO old FROM public.erp_inventory_items WHERE cafe_id=p_cafe AND item_id=saved FOR UPDATE;IF coalesce((p->>'revision')::integer,0)<>coalesce(old.revision,0) THEN RAISE EXCEPTION 'تغير الصنف أعد تحميله';END IF;
 PERFORM erp_inventory_private.assert_catalog(p_cafe,category,'category');PERFORM erp_inventory_private.assert_catalog(p_cafe,brand,'brand');PERFORM erp_inventory_private.assert_catalog(p_cafe,template,'unit_template');PERFORM erp_inventory_private.assert_catalog(p_cafe,grp,'group');
 IF template IS DISTINCT FROM old.unit_template_id AND old.item_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.bf_movements WHERE cafe_id=p_cafe AND item_id=saved) THEN RAISE EXCEPTION 'لا يمكن تغيير قالب وحدة صنف له حركات';END IF;
 IF coalesce(p->>'kind','product') IN('service','work') AND EXISTS(SELECT 1 FROM public.bf_movements WHERE cafe_id=p_cafe AND item_id=saved) THEN RAISE EXCEPTION 'لا يمكن تحويل صنف مخزني مستخدم إلى خدمة';END IF;
 INSERT INTO public.erp_inventory_settings(cafe_id) VALUES(p_cafe) ON CONFLICT DO NOTHING;SELECT payload INTO cfg FROM public.erp_inventory_settings WHERE cafe_id=p_cafe FOR UPDATE;
 PERFORM erp_inventory_private.validate_custom_values(coalesce(cfg->'itemFields','[]'),coalesce(p->'payload'->'customValues','{}'),p_cafe,saved,'item');
 FOR f IN SELECT * FROM public.erp_files WHERE cafe_id=p_cafe AND record_id=saved AND entity_type='inventory_item' AND jsonb_path_exists(coalesce(p->'payload'->'customValues','{}'),'$.** ? (@ == $file)',jsonb_build_object('file',id::text)) FOR KEY SHARE LOOP IF NOT f.uploaded OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='erp-record-files' AND name=f.path) THEN RAISE EXCEPTION 'المرفق لم يكتمل رفعه';END IF;END LOOP;
 FOREACH key IN ARRAY ARRAY['buyPrice','salePrice','minimumPrice','discount','margin','tax1','tax2'] LOOP IF p->'payload' ? key AND (jsonb_typeof(p->'payload'->key)<>'number' OR (p->'payload'->>key)::numeric NOT BETWEEN 0 AND CASE WHEN key IN('tax1','tax2') THEN 100 ELSE 1000000000 END) THEN RAISE EXCEPTION 'قيمة التسعير غير صالحة';END IF;END LOOP;
 code:=nullif(btrim(p->>'sku'),'');IF code IS NULL AND saved IS NULL THEN n:=coalesce((cfg->>'nextItemNumber')::bigint,1);LOOP code:=coalesce(cfg->>'itemPrefix','INV-')||lpad(n::text,6,'0');n:=n+1;EXIT WHEN NOT EXISTS(SELECT 1 FROM public.bf_items WHERE cafe_id=p_cafe AND sku=code);END LOOP;UPDATE public.erp_inventory_settings SET payload=jsonb_set(payload,'{nextItemNumber}',to_jsonb(n)),revision=revision+1 WHERE cafe_id=p_cafe;END IF;
 barcode:=nullif(btrim(p->>'barcode'),'');IF cfg->>'barcodeFormat'='EAN13' THEN IF barcode IS NULL AND saved IS NULL THEN n:=coalesce(n,coalesce((cfg->>'nextItemNumber')::bigint,1));LOOP barcode:=erp_inventory_private.ean13('20'||lpad(n::text,10,'0'));n:=n+1;EXIT WHEN NOT EXISTS(SELECT 1 FROM public.bf_items i WHERE i.cafe_id=p_cafe AND i.barcode=save_item.barcode);END LOOP;ELSIF barcode IS NOT NULL AND (barcode!~'^[0-9]{13}$' OR barcode<>erp_inventory_private.ean13(left(barcode,12))) THEN RAISE EXCEPTION 'رقم التحقق في باركود EAN 13 غير صالح';END IF;END IF;
 result:=public.brand_finance_execute(p_cafe,'item',jsonb_strip_nulls(jsonb_build_object('id',saved,'name',p->>'name','sku',code,'unitId',nullif(p->>'unitId',''),'barcode',barcode,'minQuantity',coalesce(p->'minQuantity','0'::jsonb))),gen_random_uuid());saved:=(result->>'id')::uuid;
 INSERT INTO public.erp_inventory_items(cafe_id,item_id,kind,status,category_id,brand_id,unit_template_id,group_id,payload) VALUES(p_cafe,saved,coalesce(p->>'kind','product'),coalesce(p->>'status','active'),category,brand,template,grp,coalesce(p->'payload','{}')) ON CONFLICT(cafe_id,item_id) DO UPDATE SET kind=excluded.kind,status=excluded.status,category_id=excluded.category_id,brand_id=excluded.brand_id,unit_template_id=excluded.unit_template_id,group_id=excluded.group_id,payload=excluded.payload,revision=erp_inventory_items.revision+1;
 UPDATE public.bf_items SET active=coalesce(p->>'status','active')='active' WHERE cafe_id=p_cafe AND id=saved;RETURN saved;
END $$;
CREATE FUNCTION public.erp_inventory_write(p_cafe uuid,p_command jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
#variable_conflict use_variable
DECLARE action text:=p_command->>'action';p jsonb:=coalesce(p_command->'payload','{}');request uuid:=(p_command->>'requestId')::uuid;id uuid:=nullif(p_command->>'id','')::uuid;rev integer:=coalesce((p_command->>'revision')::integer,0);old erp_inventory_private.requests%ROWTYPE;d public.erp_inventory_documents%ROWTYPE;c public.erp_inventory_catalogs%ROWTYPE;result jsonb;v jsonb;x jsonb;kind text;name text;wid uuid;fid uuid;counted integer;BEGIN
 IF p_command IS NULL OR jsonb_typeof(p_command)<>'object' OR request IS NULL OR octet_length(p_command::text)>1000000 OR p_command::text ~* '"[-+]?(nan|infinity)"' THEN RAISE EXCEPTION 'طلب المخزون غير صالح';END IF;
 PERFORM erp_inventory_private.authorize(p_cafe,CASE WHEN action IN('settings','employee_warehouse') THEN 'settings' WHEN action='delete' THEN 'delete' WHEN action IN('post','reverse','fulfill','acknowledge') THEN 'approve' WHEN id IS NULL THEN 'create' ELSE 'update' END);
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,60412));PERFORM brand_finance_private.seed(p_cafe);PERFORM brand_finance_private.inventory_catalog_seed(p_cafe);
 SELECT * INTO old FROM erp_inventory_private.requests WHERE cafe_id=p_cafe AND request_id=request;IF FOUND THEN IF old.payload<>p_command OR old.actor<>auth.uid() THEN RAISE EXCEPTION 'معرف الطلب مستخدم لعملية أخرى';END IF;RETURN old.result||'{"duplicate":true}'::jsonb;END IF;
 IF action='item' THEN id:=erp_inventory_private.save_item(p_cafe,p||jsonb_build_object('id',id,'revision',rev));
 ELSIF action='import_items' THEN
 IF jsonb_typeof(p->'rows') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'rows') NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'الاستيراد من ١ إلى ١٠٠ صنف';END IF;FOR v IN SELECT value FROM jsonb_array_elements(p->'rows') LOOP IF nullif(v->>'id','') IS NOT NULL THEN PERFORM erp_inventory_private.authorize(p_cafe,'update');END IF;id:=erp_inventory_private.save_item(p_cafe,v);END LOOP;result:=jsonb_build_object('count',jsonb_array_length(p->'rows'));
 ELSIF action='catalog' THEN
 kind:=p->>'kind';IF id IS NOT NULL THEN SELECT * INTO c FROM public.erp_inventory_catalogs WHERE cafe_id=p_cafe AND erp_inventory_catalogs.id=id FOR UPDATE;IF c.id IS NULL OR c.kind<>kind OR c.revision<>rev THEN RAISE EXCEPTION 'تغير السجل أعد تحميله';END IF;END IF;
 IF kind='unit_template' THEN
 IF jsonb_typeof(p->'units') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'units') NOT BETWEEN 1 AND 30 OR (SELECT count(*) FROM jsonb_array_elements(p->'units') u WHERE (u->>'factor')::numeric=1)<>1 THEN RAISE EXCEPTION 'حدد وحدة أساسية واحدة بمعامل ١';END IF;
 FOR v IN SELECT value FROM jsonb_array_elements(p->'units') LOOP IF length(btrim(coalesce(v->>'name',''))) NOT BETWEEN 1 AND 30 OR (v->>'factor')::numeric NOT BETWEEN 0.000001 AND 1000000 THEN RAISE EXCEPTION 'اسم الوحدة أو معامل التحويل غير صالح';END IF;END LOOP;
 IF (SELECT count(DISTINCT u->>'name') FROM jsonb_array_elements(p->'units') u)<>jsonb_array_length(p->'units') THEN RAISE EXCEPTION 'أسماء الوحدات مكررة';END IF;
 IF c.id IS NOT NULL AND c.payload->'units' IS DISTINCT FROM p->'units' AND EXISTS(SELECT 1 FROM public.erp_inventory_items i JOIN public.bf_movements m ON m.cafe_id=i.cafe_id AND m.item_id=i.item_id WHERE i.cafe_id=p_cafe AND i.unit_template_id=id) THEN RAISE EXCEPTION 'لا يمكن تغيير تحويلات قالب مستخدم في حركات';END IF;
 END IF;
 IF kind='category' AND nullif(p->>'parentId','') IS NOT NULL THEN PERFORM erp_inventory_private.assert_catalog(p_cafe,(p->>'parentId')::uuid,'category');IF id=(p->>'parentId')::uuid OR EXISTS(WITH RECURSIVE parents AS(SELECT q.id,q.parent_id FROM public.erp_inventory_catalogs q WHERE q.cafe_id=p_cafe AND q.id=(p->>'parentId')::uuid UNION ALL SELECT q.id,q.parent_id FROM public.erp_inventory_catalogs q JOIN parents pr ON pr.parent_id=q.id WHERE q.cafe_id=p_cafe) SELECT 1 FROM parents WHERE parents.id=id) THEN RAISE EXCEPTION 'التصنيف الرئيسي يؤدي إلى حلقة';END IF;END IF;
 id:=coalesce(id,gen_random_uuid());INSERT INTO public.erp_inventory_catalogs(id,cafe_id,kind,name,active,payload) VALUES(id,p_cafe,kind,btrim(p->>'name'),coalesce((p->>'active')::boolean,true),p-'name'-'kind'-'active') ON CONFLICT ON CONSTRAINT erp_inventory_catalogs_cafe_id_id_key DO UPDATE SET name=excluded.name,active=excluded.active,payload=excluded.payload,revision=erp_inventory_catalogs.revision+1;
 UPDATE public.erp_inventory_catalogs q SET parent_id=CASE WHEN kind='category' THEN nullif(p->>'parentId','')::uuid ELSE NULL END WHERE q.cafe_id=p_cafe AND q.id=id;
 IF kind='unit_template' THEN INSERT INTO public.bf_item_units(cafe_id,name) SELECT p_cafe,u->>'name' FROM jsonb_array_elements(p->'units') u ON CONFLICT ON CONSTRAINT bf_item_units_cafe_id_name_key DO NOTHING;END IF;
 IF kind='group' AND p ? 'items' THEN IF jsonb_typeof(p->'items') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'items') NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'أضف من ١ إلى ١٠٠ متغير';END IF;FOR v IN SELECT value FROM jsonb_array_elements(p->'items') LOOP PERFORM erp_inventory_private.save_item(p_cafe,v||jsonb_build_object('groupId',id,'categoryId',p->>'categoryId','brandId',p->>'brandId'));END LOOP;END IF;
 ELSIF action='warehouse' THEN
 IF id IS NOT NULL THEN SELECT inventory_revision INTO counted FROM public.bf_warehouses WHERE cafe_id=p_cafe AND bf_warehouses.id=id FOR UPDATE;IF counted IS NULL OR counted<>rev OR NOT erp_inventory_private.warehouse_allowed(p_cafe,id,'edit') THEN RAISE EXCEPTION 'المستودع تغير أو لا تملك تعديله';END IF;END IF;
 IF coalesce((p->>'isDefault')::boolean,false) AND NOT coalesce((p->>'active')::boolean,true) THEN RAISE EXCEPTION 'المستودع الافتراضي يجب أن يكون نشطًا';END IF;
 IF id IS NOT NULL AND EXISTS(SELECT 1 FROM public.bf_warehouses WHERE cafe_id=p_cafe AND bf_warehouses.id=id AND is_default) AND (NOT coalesce((p->>'isDefault')::boolean,false) OR NOT coalesce((p->>'active')::boolean,true)) THEN RAISE EXCEPTION 'عين مستودعًا رئيسيًا آخر قبل تعطيل الحالي';END IF;
 IF NOT coalesce((p->>'active')::boolean,true) AND EXISTS(SELECT 1 FROM public.bf_stock WHERE cafe_id=p_cafe AND warehouse_id=id AND quantity<>0) THEN RAISE EXCEPTION 'لا يمكن تعطيل مستودع له رصيد';END IF;
 FOR kind,v IN SELECT key,value FROM jsonb_each(coalesce(p->'permissions','{}')) LOOP IF kind NOT IN('read','write','edit') OR coalesce(v->>'mode','all') NOT IN('all','employees','roles','branches') OR jsonb_typeof(coalesce(v->'ids','[]'))<>'array' THEN RAISE EXCEPTION 'صلاحيات المستودع غير صالحة';END IF;FOR x IN SELECT value FROM jsonb_array_elements(coalesce(v->'ids','[]')) LOOP IF v->>'mode'='employees' AND NOT EXISTS(SELECT 1 FROM public.erp_hr_employees WHERE cafe_id=p_cafe AND erp_hr_employees.id=(x#>>'{}')::uuid) OR v->>'mode'='branches' AND NOT EXISTS(SELECT 1 FROM public.branches WHERE cafe_id=p_cafe AND branches.id=(x#>>'{}')::uuid) OR v->>'mode'='roles' AND x#>>'{}' NOT IN('manager','cashier','accountant','warehouse','auditor') THEN RAISE EXCEPTION 'اختيار الصلاحيات خارج العلامة';END IF;END LOOP;END LOOP;
 IF coalesce((p->>'isDefault')::boolean,false) THEN UPDATE public.bf_warehouses SET is_default=false,inventory_revision=inventory_revision+1 WHERE cafe_id=p_cafe AND is_default AND bf_warehouses.id IS DISTINCT FROM id;END IF;
 id:=coalesce(id,gen_random_uuid());INSERT INTO public.bf_warehouses(id,cafe_id,name,active,is_default,inventory_payload) VALUES(id,p_cafe,btrim(p->>'name'),coalesce((p->>'active')::boolean,true),coalesce((p->>'isDefault')::boolean,false),p-'name'-'active'-'isDefault') ON CONFLICT ON CONSTRAINT bf_warehouses_cafe_id_id_key DO UPDATE SET name=excluded.name,active=excluded.active,is_default=excluded.is_default,inventory_payload=excluded.inventory_payload,inventory_revision=bf_warehouses.inventory_revision+1;
 ELSIF action='employee_warehouse' THEN
 id:=(p->>'employeeId')::uuid;wid:=nullif(p->>'warehouseId','')::uuid;IF NOT EXISTS(SELECT 1 FROM public.erp_hr_employees WHERE cafe_id=p_cafe AND erp_hr_employees.id=id AND active) THEN RAISE EXCEPTION 'اختر موظفًا نشطًا';END IF;IF wid IS NULL THEN DELETE FROM public.erp_inventory_employee_warehouses WHERE cafe_id=p_cafe AND employee_id=id;ELSE IF NOT EXISTS(SELECT 1 FROM public.bf_warehouses WHERE cafe_id=p_cafe AND bf_warehouses.id=wid AND active) THEN RAISE EXCEPTION 'اختر مستودعًا نشطًا';END IF;INSERT INTO public.erp_inventory_employee_warehouses VALUES(p_cafe,id,wid) ON CONFLICT(cafe_id,employee_id) DO UPDATE SET warehouse_id=excluded.warehouse_id;END IF;
 ELSIF action='settings' THEN
 SELECT revision INTO counted FROM public.erp_inventory_settings WHERE cafe_id=p_cafe FOR UPDATE;IF coalesce(counted,0)<>rev THEN RAISE EXCEPTION 'تغيرت الإعدادات أعد تحميلها';END IF;
 PERFORM erp_manufacturing_private.validate_custom_fields(coalesce(p->'itemFields','[]'));
 IF coalesce((p->>'nextItemNumber')::bigint,1) NOT BETWEEN 1 AND 999999999 OR coalesce((p->>'nextDocumentNumber')::bigint,1) NOT BETWEEN 1 AND 999999999 OR length(coalesce(p->>'itemPrefix',''))>20 THEN RAISE EXCEPTION 'إعدادات الترقيم غير صالحة';END IF;
 IF nullif(p->>'barcodePattern','') IS NOT NULL AND (p->>'barcodePattern' !~ '^[XWPN]{2,64}$' OR position('X' IN p->>'barcodePattern')=0 OR position('W' IN p->>'barcodePattern')=0 AND position('P' IN p->>'barcodePattern')=0 OR coalesce((p->>'barcodeWeightDivisor')::numeric,1000)<=0 OR coalesce((p->>'barcodePriceDivisor')::numeric,100)<=0) THEN RAISE EXCEPTION 'صيغة الباركود أو تقسيم الوحدات غير صالح';END IF;
 IF coalesce((p->>'embeddedBarcode')::boolean,false) AND (coalesce((p->>'barcodeLength')::integer,13) NOT BETWEEN 1 AND 64 OR coalesce((p->>'barcodeProductStart')::integer,3)<1 OR coalesce((p->>'barcodeProductLength')::integer,5)<1 OR coalesce((p->>'barcodeValueStart')::integer,8)<1 OR coalesce((p->>'barcodeValueLength')::integer,5)<1 OR coalesce((p->>'barcodeDecimals')::integer,3) NOT BETWEEN 0 AND 6 OR coalesce((p->>'barcodeProductStart')::integer,3)+coalesce((p->>'barcodeProductLength')::integer,5)-1>coalesce((p->>'barcodeLength')::integer,13) OR coalesce((p->>'barcodeValueStart')::integer,8)+coalesce((p->>'barcodeValueLength')::integer,5)-1>coalesce((p->>'barcodeLength')::integer,13)) THEN RAISE EXCEPTION 'مواقع حقول الباركود خارج النطاق';END IF;
 INSERT INTO public.erp_inventory_settings(cafe_id,payload) VALUES(p_cafe,p) ON CONFLICT(cafe_id) DO UPDATE SET payload=excluded.payload,revision=erp_inventory_settings.revision+1;id:=p_cafe;
 ELSIF action='document' THEN
 IF id IS NOT NULL THEN SELECT * INTO d FROM public.erp_inventory_documents WHERE cafe_id=p_cafe AND erp_inventory_documents.id=id FOR UPDATE;IF d.id IS NULL OR d.revision<>rev OR d.status NOT IN('draft','pending','counted') OR d.source_mode<>'standalone' THEN RAISE EXCEPTION 'لا يمكن تعديل هذا المستند أو تغيرت نسخته';END IF;END IF;
 wid:=(p->>'warehouseId')::uuid;IF NOT erp_inventory_private.warehouse_allowed(p_cafe,wid,'write') THEN RAISE EXCEPTION 'لا تملك استخدام المستودع';END IF;
 id:=coalesce(id,gen_random_uuid());kind:=p->>'kind';IF d.id IS NOT NULL AND d.kind<>kind THEN RAISE EXCEPTION 'نوع المستند لا يتغير';END IF;
 IF kind='request' AND (SELECT payload->>'stockRequests' FROM public.erp_inventory_settings WHERE cafe_id=p_cafe)='false' THEN RAISE EXCEPTION 'الطلبات المخزنية غير مفعلة';END IF;
 IF nullif(btrim(p->>'code'),'') IS NULL AND d.id IS NULL THEN INSERT INTO public.erp_inventory_settings(cafe_id) VALUES(p_cafe) ON CONFLICT DO NOTHING;SELECT coalesce((payload->>'nextDocumentNumber')::integer,1) INTO counted FROM public.erp_inventory_settings WHERE cafe_id=p_cafe FOR UPDATE;LOOP name:=upper(left(kind,3))||'-'||lpad(counted::text,6,'0');counted:=counted+1;EXIT WHEN NOT EXISTS(SELECT 1 FROM public.erp_inventory_documents q WHERE q.cafe_id=p_cafe AND q.kind=kind AND q.code=name);END LOOP;p:=p||jsonb_build_object('code',name);UPDATE public.erp_inventory_settings SET payload=jsonb_set(payload,'{nextDocumentNumber}',to_jsonb(counted)),revision=revision+1 WHERE cafe_id=p_cafe;END IF;
 INSERT INTO public.erp_inventory_documents(id,cafe_id,code,kind,warehouse_id,to_warehouse_id,party_id,effective_on,payload,created_by) VALUES(id,p_cafe,coalesce(nullif(btrim(p->>'code'),''),upper(left(kind,3))||'-'||left(id::text,8)),kind,wid,nullif(p->>'toWarehouseId','')::uuid,nullif(p->>'partyId','')::uuid,(p->>'effectiveOn')::date,coalesce(p->'payload','{}'),auth.uid()) ON CONFLICT ON CONSTRAINT erp_inventory_documents_cafe_id_id_key DO UPDATE SET code=excluded.code,warehouse_id=excluded.warehouse_id,to_warehouse_id=excluded.to_warehouse_id,party_id=excluded.party_id,effective_on=excluded.effective_on,payload=excluded.payload,status='draft',revision=erp_inventory_documents.revision+1;
 PERFORM erp_inventory_private.save_lines(p_cafe,id,coalesce(p->'lines','[]'));
 ELSIF action='acknowledge' THEN id:=erp_inventory_private.acknowledge_finance(p_cafe,(p->>'financeDocumentId')::uuid);
 ELSE
 SELECT * INTO d FROM public.erp_inventory_documents WHERE cafe_id=p_cafe AND erp_inventory_documents.id=id FOR UPDATE;
 IF action='delete' AND p->>'entity'='catalog' THEN DELETE FROM public.erp_inventory_catalogs WHERE cafe_id=p_cafe AND erp_inventory_catalogs.id=id AND revision=rev;IF NOT FOUND THEN RAISE EXCEPTION 'السجل غير متاح أو تغير';END IF;
 ELSE IF d.id IS NULL OR d.revision<>rev OR NOT erp_inventory_private.warehouse_allowed(p_cafe,d.warehouse_id,'write') THEN RAISE EXCEPTION 'المستند غير متاح أو تغير';END IF;
 IF d.source_mode='financial' AND action<>'note' THEN RAISE EXCEPTION 'عالج الإذن من مستند المشتريات الأصلي';END IF;
 CASE action
 WHEN 'post' THEN fid:=erp_inventory_private.post(p_cafe,id);
 WHEN 'reverse' THEN fid:=erp_inventory_private.reverse(p_cafe,id);
 WHEN 'submit' THEN IF d.status<>'draft' OR d.kind<>'request' THEN RAISE EXCEPTION 'أرسل طلبًا مخزنيًا مسودة';END IF;UPDATE public.erp_inventory_documents SET status='pending',revision=revision+1 WHERE cafe_id=p_cafe AND erp_inventory_documents.id=id;
 WHEN 'fulfill' THEN
 IF d.kind<>'request' OR d.status<>'pending' THEN RAISE EXCEPTION 'اختر طلبًا مخزنيًا بانتظار التنفيذ';END IF;kind:=coalesce(p->>'kind','issue');IF kind NOT IN('receipt','issue','transfer') THEN RAISE EXCEPTION 'نوع التنفيذ غير صالح';END IF;fid:=gen_random_uuid();INSERT INTO public.erp_inventory_documents(id,cafe_id,code,kind,warehouse_id,to_warehouse_id,party_id,effective_on,request_document_id,payload,created_by) VALUES(fid,p_cafe,kind||'-'||d.code,kind,d.warehouse_id,d.to_warehouse_id,d.party_id,current_date,id,d.payload,auth.uid());INSERT INTO public.erp_inventory_lines(cafe_id,document_id,item_id,quantity,factor,unit_name,unit_cost,expected_quantity,counted_quantity,payload,position) SELECT cafe_id,fid,item_id,quantity,factor,unit_name,unit_cost,expected_quantity,counted_quantity,payload,position FROM public.erp_inventory_lines WHERE cafe_id=p_cafe AND document_id=id;PERFORM erp_inventory_private.post(p_cafe,fid);UPDATE public.erp_inventory_documents SET status='posted',revision=revision+1 WHERE cafe_id=p_cafe AND erp_inventory_documents.id=id;result:=jsonb_build_object('id',fid,'requestId',id);
 WHEN 'import_warehouse' THEN
 IF d.kind<>'stocktake' OR d.status NOT IN('draft','counted') THEN RAISE EXCEPTION 'اختر ورقة جرد مسودة';END IF;INSERT INTO public.erp_inventory_lines(cafe_id,document_id,item_id,quantity,unit_name,unit_cost,expected_quantity,position) SELECT p_cafe,id,i.id,0,i.unit,coalesce(s.average_cost,0),coalesce(s.quantity,0),row_number() OVER(ORDER BY i.name) FROM public.bf_items i LEFT JOIN public.bf_stock s ON s.cafe_id=i.cafe_id AND s.item_id=i.id AND s.warehouse_id=d.warehouse_id LEFT JOIN public.erp_inventory_items meta ON meta.cafe_id=i.cafe_id AND meta.item_id=i.id WHERE i.cafe_id=p_cafe AND i.active AND coalesce(meta.kind,'product')='product' ON CONFLICT(cafe_id,document_id,item_id) DO NOTHING;UPDATE public.erp_inventory_documents SET status='draft',revision=revision+1 WHERE cafe_id=p_cafe AND erp_inventory_documents.id=id;
 WHEN 'sync_count' THEN
 IF d.kind<>'stocktake' OR d.status NOT IN('draft','counted') THEN RAISE EXCEPTION 'الجرد غير قابل للمزامنة';END IF;UPDATE public.erp_inventory_lines l SET expected_quantity=coalesce((SELECT s.quantity FROM public.bf_stock s WHERE s.cafe_id=p_cafe AND s.item_id=l.item_id AND s.warehouse_id=d.warehouse_id),0) WHERE l.cafe_id=p_cafe AND l.document_id=id;UPDATE public.erp_inventory_documents SET status='draft',revision=revision+1,payload=payload||jsonb_build_object('syncedAt',now()) WHERE cafe_id=p_cafe AND erp_inventory_documents.id=id;
 WHEN 'finish_count' THEN IF d.kind<>'stocktake' OR d.status<>'draft' OR NOT EXISTS(SELECT 1 FROM public.erp_inventory_lines WHERE cafe_id=p_cafe AND document_id=id) OR EXISTS(SELECT 1 FROM public.erp_inventory_lines WHERE cafe_id=p_cafe AND document_id=id AND counted_quantity IS NULL) THEN RAISE EXCEPTION 'أكمل العدد الفعلي لكل بنود الجرد';END IF;UPDATE public.erp_inventory_documents SET status='counted',revision=revision+1 WHERE cafe_id=p_cafe AND erp_inventory_documents.id=id;
 WHEN 'cancel' THEN IF d.status NOT IN('draft','pending','counted') THEN RAISE EXCEPTION 'لا يمكن إلغاء مستند مرحل';END IF;UPDATE public.erp_inventory_documents SET status='cancelled',revision=revision+1 WHERE cafe_id=p_cafe AND erp_inventory_documents.id=id;
 WHEN 'delete' THEN IF d.status NOT IN('draft','cancelled') OR d.finance_document_id IS NOT NULL THEN RAISE EXCEPTION 'لا يمكن حذف مستند مستخدم';END IF;DELETE FROM public.erp_inventory_documents WHERE cafe_id=p_cafe AND erp_inventory_documents.id=id;
 WHEN 'note' THEN IF length(btrim(coalesce(p->>'note',''))) NOT BETWEEN 1 AND 4000 THEN RAISE EXCEPTION 'اكتب ملاحظة صالحة';END IF;
 ELSE RAISE EXCEPTION 'إجراء مخزني غير معروف';END CASE;END IF;
 END IF;
 result:=coalesce(result,jsonb_build_object('id',id,'financeDocumentId',fid));INSERT INTO public.erp_inventory_events(cafe_id,record_id,action,detail,actor) VALUES(p_cafe,coalesce(id,p_cafe),action,CASE WHEN action='note' THEN p ELSE jsonb_build_object('result',result) END,auth.uid());INSERT INTO erp_inventory_private.requests VALUES(p_cafe,request,auth.uid(),p_command,result);RETURN result;
END $$;
CREATE FUNCTION public.erp_inventory_read(p_cafe uuid,p_query jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE r text;result jsonb;selected uuid:=nullif(p_query->>'id','')::uuid;BEGIN
 r:=erp_inventory_private.authorize(p_cafe);PERFORM brand_finance_private.seed(p_cafe);PERFORM brand_finance_private.inventory_catalog_seed(p_cafe);
 result:=jsonb_build_object('canWrite',r IN('owner','manager','warehouse'),'settings',coalesce((SELECT to_jsonb(s)-'cafe_id' FROM public.erp_inventory_settings s WHERE cafe_id=p_cafe),'{"payload":{},"revision":0}'),
 'warehouses',coalesce((SELECT jsonb_agg(to_jsonb(w)-'cafe_id' ORDER BY w.is_default DESC,w.name) FROM public.bf_warehouses w WHERE cafe_id=p_cafe AND erp_inventory_private.warehouse_allowed(p_cafe,w.id,'read')),'[]'),
 'defaultWarehouseId',erp_inventory_private.default_warehouse(p_cafe),
 'items',coalesce((SELECT jsonb_agg(to_jsonb(i)-'cafe_id'||jsonb_build_object('meta',coalesce(to_jsonb(m)-'cafe_id'-'item_id','{"kind":"product","status":"active","payload":{},"revision":0}'::jsonb),'quantity',coalesce((SELECT sum(s.quantity) FROM public.bf_stock s WHERE s.cafe_id=p_cafe AND s.item_id=i.id AND erp_inventory_private.warehouse_allowed(p_cafe,s.warehouse_id,'read')),0)) ORDER BY i.name) FROM public.bf_items i LEFT JOIN public.erp_inventory_items m ON m.cafe_id=i.cafe_id AND m.item_id=i.id WHERE i.cafe_id=p_cafe),'[]'),
 'catalogs',coalesce((SELECT jsonb_agg(to_jsonb(c)-'cafe_id' ORDER BY kind,name) FROM public.erp_inventory_catalogs c WHERE cafe_id=p_cafe),'[]'),
 'units',coalesce((SELECT jsonb_agg(to_jsonb(u)-'cafe_id' ORDER BY name) FROM public.bf_item_units u WHERE cafe_id=p_cafe),'[]'),
 'stock',coalesce((SELECT jsonb_agg(to_jsonb(s)-'cafe_id') FROM public.bf_stock s WHERE cafe_id=p_cafe AND erp_inventory_private.warehouse_allowed(p_cafe,s.warehouse_id,'read')),'[]'),
 'documents',coalesce((SELECT jsonb_agg(to_jsonb(d)-'cafe_id'||jsonb_build_object('lines',coalesce((SELECT jsonb_agg(to_jsonb(l)-'cafe_id' ORDER BY position) FROM public.erp_inventory_lines l WHERE l.cafe_id=p_cafe AND l.document_id=d.id),'[]')) ORDER BY d.created_at DESC) FROM (SELECT * FROM public.erp_inventory_documents q WHERE cafe_id=p_cafe AND (selected IS NULL OR q.id=selected) AND erp_inventory_private.warehouse_allowed(p_cafe,q.warehouse_id,'read') ORDER BY created_at DESC LIMIT 1000) d),'[]'),
 'events',coalesce((SELECT jsonb_agg(to_jsonb(e)-'cafe_id' ORDER BY e.created_at DESC) FROM(SELECT * FROM public.erp_inventory_events WHERE cafe_id=p_cafe AND record_id=selected ORDER BY created_at DESC LIMIT 200) e),'[]'),
 'employees',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',first_name||' '||last_name,'code',code,'userId',user_id) ORDER BY first_name,last_name) FROM public.erp_hr_employees WHERE cafe_id=p_cafe AND active),'[]'),
 'employeeWarehouses',coalesce((SELECT jsonb_agg(to_jsonb(e)-'cafe_id') FROM public.erp_inventory_employee_warehouses e WHERE cafe_id=p_cafe),'[]'),
 'branches',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name)) FROM public.branches WHERE cafe_id=p_cafe AND active AND deleted_at IS NULL),'[]'),
 'parties',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name,'kind',kind)) FROM public.bf_parties WHERE cafe_id=p_cafe AND active),'[]'),
 'accounts',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name,'code',code,'kind',kind)) FROM public.bf_accounts WHERE cafe_id=p_cafe AND active AND kind IN('expense','equity')),'[]'),
 'financialSources',coalesce((SELECT jsonb_agg(to_jsonb(d)) FROM(SELECT b.id,b.number,b.kind,b.created_at,b.warehouse_id,b.note FROM public.bf_documents b WHERE b.cafe_id=p_cafe AND b.kind IN('sale','purchase','refund') AND EXISTS(SELECT 1 FROM public.bf_movements WHERE cafe_id=p_cafe AND document_id=b.id) AND NOT EXISTS(SELECT 1 FROM public.erp_inventory_documents WHERE cafe_id=p_cafe AND finance_document_id=b.id) AND erp_inventory_private.warehouse_allowed(p_cafe,b.warehouse_id,'read') ORDER BY b.created_at DESC LIMIT 200) d),'[]'),
 'movements',coalesce((SELECT jsonb_agg(to_jsonb(m)-'cafe_id') FROM(SELECT * FROM public.bf_movements WHERE cafe_id=p_cafe AND (selected IS NULL OR item_id=selected OR document_id IN(SELECT finance_document_id FROM public.erp_inventory_documents WHERE cafe_id=p_cafe AND id=selected)) AND erp_inventory_private.warehouse_allowed(p_cafe,warehouse_id,'read') ORDER BY created_at DESC LIMIT 1000) m),'[]'));
 RETURN erp_access_private.mask_snapshot(p_cafe,'inventory',result);
END $$;
-- Extend files by delegation so previously installed guards retain their exact behavior
ALTER FUNCTION erp_file_private.assert_record(uuid,text,uuid,boolean) RENAME TO assert_record_before_inventory;
CREATE FUNCTION erp_file_private.assert_record(p_cafe uuid,p_type text,p_record uuid,p_write boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE found_id uuid;wh uuid;BEGIN
 IF p_type NOT IN('inventory_document','inventory_item','inventory_catalog') THEN PERFORM erp_file_private.assert_record_before_inventory(p_cafe,p_type,p_record,p_write);RETURN;END IF;
 PERFORM erp_inventory_private.authorize(p_cafe,CASE WHEN p_write THEN 'files' ELSE 'read' END);
 IF p_type='inventory_document' THEN SELECT id,warehouse_id INTO found_id,wh FROM public.erp_inventory_documents WHERE cafe_id=p_cafe AND id=p_record FOR KEY SHARE;IF found_id IS NOT NULL AND NOT erp_inventory_private.warehouse_allowed(p_cafe,wh,CASE WHEN p_write THEN 'write' ELSE 'read' END) THEN found_id:=NULL;END IF;
 ELSIF p_type='inventory_catalog' THEN SELECT id INTO found_id FROM public.erp_inventory_catalogs WHERE cafe_id=p_cafe AND id=p_record FOR KEY SHARE;
 ELSE SELECT id INTO found_id FROM public.bf_items WHERE cafe_id=p_cafe AND id=p_record FOR KEY SHARE;END IF;
 IF found_id IS NULL THEN RAISE EXCEPTION 'سجل المرفق غير متاح' USING ERRCODE='42501';END IF;
END $$;
CREATE TRIGGER erp_file_orphan_guard BEFORE DELETE ON public.erp_inventory_documents FOR EACH ROW EXECUTE FUNCTION erp_file_private.prevent_orphans('inventory_document');
CREATE TRIGGER erp_inventory_catalog_file_orphan BEFORE DELETE ON public.erp_inventory_catalogs FOR EACH ROW EXECUTE FUNCTION erp_file_private.prevent_orphans('inventory_catalog');
CREATE TRIGGER erp_inventory_item_file_orphan BEFORE DELETE ON public.bf_items FOR EACH ROW EXECUTE FUNCTION erp_file_private.prevent_orphans('inventory_item');
ALTER FUNCTION erp_access_private.file_domain(text) RENAME TO file_domain_before_inventory;
CREATE FUNCTION erp_access_private.file_domain(p_type text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path='' AS $$SELECT CASE WHEN p_type IN('inventory_item','inventory_document','inventory_catalog') THEN 'inventory' ELSE erp_access_private.file_domain_before_inventory(p_type) END$$;
DO $$ DECLARE definition text;BEGIN SELECT pg_get_functiondef('public.erp_file_delete_access(text)'::regprocedure) INTO definition;EXECUTE replace(definition,'public.erp_file_delete_access(','erp_inventory_private.file_delete_access_before_inventory(');END $$;
CREATE OR REPLACE FUNCTION public.erp_file_delete_access(p_path text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE f public.erp_files%ROWTYPE;BEGIN IF NOT erp_inventory_private.file_delete_access_before_inventory(p_path) THEN RETURN false;END IF;SELECT * INTO f FROM public.erp_files WHERE path=p_path FOR UPDATE;IF f.entity_type='inventory_item' AND EXISTS(SELECT 1 FROM public.erp_inventory_items WHERE cafe_id=f.cafe_id AND item_id=f.record_id AND jsonb_path_exists(coalesce(payload->'customValues','{}'),'$.** ? (@ == $file)',jsonb_build_object('file',f.id::text))) THEN RETURN false;END IF;RETURN true;END $$;
REVOKE ALL ON FUNCTION public.erp_file_delete_access(text) FROM PUBLIC,anon,service_role;
GRANT EXECUTE ON FUNCTION public.erp_file_delete_access(text) TO authenticated;
REVOKE ALL ON FUNCTION erp_file_private.assert_record(uuid,text,uuid,boolean),erp_file_private.assert_record_before_inventory(uuid,text,uuid,boolean),erp_access_private.file_domain(text),erp_access_private.file_domain_before_inventory(text) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA erp_inventory_private FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.erp_inventory_read(uuid,jsonb),public.erp_inventory_write(uuid,jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.erp_inventory_read(uuid,jsonb),public.erp_inventory_write(uuid,jsonb) TO authenticated;
NOTIFY pgrst,'reload schema';
COMMIT;
